#---------------------
# Prep tidal data for regression fitting to get a good fitting curve. 

# Convert DateTime to numeric hours from start (model needs numeric time)
t0 <- min(tides$DateTime)
tides$hours <- as.numeric(difftime(tides$DateTime, t0, units = "hours"))

# Tidal constituent periods (hours)
M2 <- 12.4206
S2 <- 12.0000
K1 <- 23.9345
O1 <- 25.8194

# Build harmonic regression
# Each constituent gets a sin + cos pair (handles amplitude and phase)
harm_fit <- lm(Metres ~ 
                 sin(2*pi*hours/M2) + cos(2*pi*hours/M2) +
                 sin(2*pi*hours/S2) + cos(2*pi*hours/S2) +
                 sin(2*pi*hours/K1) + cos(2*pi*hours/K1) +
                 sin(2*pi*hours/O1) + cos(2*pi*hours/O1),
               data = tides)

summary(harm_fit)

# Predict on a fine grid for smooth curve
hours_fine <- seq(min(tides$hours), max(tides$hours), by = 0.25)
tpred_df <- data.frame(hours = hours_fine)
tpred_df$DateTime <- t0 + hours_fine * 3600
tpred_df$fit <- predict(harm_fit, newdata = tpred_df)

# Fitted tidal plot ... 
