  geom_point(data = tides, aes(x = DateTime, y = Metres), 
             size = 0.8, colour = "grey50") +
  geom_line(data = pred_df, aes(x = DateTime, y = fit),
            colour = "steelblue", linewidth = 0.8) +
  labs(x = "Date", y = "Water Level (m)",
       title = "Alert Bay — Harmonic Tidal Fit (M2, S2, K1, O1)")



